class JpegBitReader:
def __init__(self,data,pos):
self.data = data
self.pos = pos
self.bits = 0
self.nBits = 0
def Fill(self):
while self.nBits<=24:
if self.pos>=len(self.data):
self.bits = (self.bits<<8)|0
self.nBits += 8
continue
b = self.data[self.pos]
if b==0xFF:
nxt = self.data[self.pos+1] if self.pos+1<len(self.data) else 0xD9
if nxt==0x00:
self.pos += 2
else:
self.bits = (self.bits<<8)|0 #a marker: feed zeros
self.nBits += 8
continue
else:
self.pos += 1
self.bits = (self.bits<<8)|b
self.nBits += 8
def Peek8(self):
if self.nBits<8:
self.Fill()
return (self.bits>>(self.nBits-8))&0xFF
def Skip(self,n):
self.nBits -= n
self.bits &= (1<<self.nBits)-1
def Receive(self,n):
if n==0:
return 0
if self.nBits<n:
self.Fill()
v = (self.bits>>(self.nBits-n))&((1<<n)-1)
self.Skip(n)
return v
def Restart(self):
self.bits = 0
self.nBits = 0
while self.pos+1<len(self.data):
if self.data[self.pos]==0xFF and 0xD0<=self.data[self.pos+1]<=0xD7:
self.pos += 2
